// A single pass prevents translations from translating themselves or matching inside words.
export function createTranslator(dictionary: Record<string, string>): (value: string) => string {
  const normalized = Object.fromEntries(Object.entries(dictionary).map(([key, value]) => [key.trim(), value.trim()]));
  const escaped = Object.keys(normalized).filter(Boolean).sort((a, b) => b.length - a.length)
    .map(key => key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  if (!escaped.length) return value => value;
  const pattern = new RegExp(`(?<![\\p{L}\\p{N}])(?:${escaped.join('|')})(?![\\p{L}\\p{N}])`, 'gu');
  return value => {
    const translated = value.replace(pattern, match => normalized[match]);
    // Leave unknown phrases intact rather than showing a half-English sentence.
    return /[\u0621-\u064a\u066e-\u06d3]/u.test(translated) ? value : translated;
  };
}

export function translatePhrase(value: string, dictionary: Record<string, string>): string {
  return createTranslator(dictionary)(value);
}

export function publicCopy(value: string, language: 'ar' | 'en'): string {
  return language === 'en' ? UI_COPY[value] ?? value : value;
}

