// Track what we rendered so a later React update does not resurrect stale copy.
const englishOriginalText=new WeakMap<Text,{original:string;translated:string}>();
const englishOriginalAttrs=new WeakMap<HTMLElement,Record<string,{original:string;translated:string}>>();
const translateEnglish=createTranslator({...EN,...EN_MORE,...UI_COPY,...STUDY_COPY,...SECTION_COPY});
export function applyEnglish(root:HTMLElement,enabled:boolean){
 const skip=(el:Element|null)=>!!el?.closest('script,style,noscript,textarea,input,[contenteditable="true"],[translate="no"],[data-no-translate]');
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 const nodes:Text[]=[];
 while(walker.nextNode())nodes.push(walker.currentNode as Text);
 for(const node of nodes){
  if(skip(node.parentElement))continue;
  const current=node.nodeValue||'';
  const saved=englishOriginalText.get(node);
  const original=saved&&current===saved.translated?saved.original:current;
  const translated=enabled?translateEnglish(original):original;
  if(enabled)englishOriginalText.set(node,{original,translated});else englishOriginalText.delete(node);
  if(current!==translated)node.nodeValue=translated;
 }
 root.querySelectorAll<HTMLElement>('[placeholder],[aria-label],[title],[alt]').forEach(el=>{
  if(el.closest('[translate="no"],[data-no-translate]'))return;
  const saved=englishOriginalAttrs.get(el)||{};
  for(const attr of ['placeholder','aria-label','title','alt']){
   const current=el.getAttribute(attr);if(current===null){delete saved[attr];continue;}
   const previous=saved[attr];
   const original=previous&&current===previous.translated?previous.original:current;
   const translated=enabled?translateEnglish(original):original;
   if(enabled)saved[attr]={original,translated};else delete saved[attr];
   if(current!==translated)el.setAttribute(attr,translated);
  }
  if(enabled)englishOriginalAttrs.set(el,saved);else englishOriginalAttrs.delete(el);
 });
  }
